CREATE FUNCTION public.recalculate_trip_verification_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; BEGIN FOR d IN SELECT source_workspace_id,selected_workspace_id FROM public.trip_distributions WHERE trip_id=NEW.id LOOP PERFORM public.recalculate_membership_verification(d.source_workspace_id); PERFORM public.recalculate_membership_verification(d.selected_workspace_id); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER provider_completed_trip_recalculate AFTER UPDATE OF status,completed_at ON public.trips FOR EACH ROW EXECUTE FUNCTION public.recalculate_trip_verification_event();
CREATE TRIGGER credential_evidence_insert_guard BEFORE INSERT ON public.provider_credentials FOR EACH ROW EXECUTE FUNCTION public.guard_verification_evidence_linkage();
CREATE TRIGGER payout_evidence_insert_guard BEFORE INSERT ON public.provider_payout_accounts FOR EACH ROW EXECUTE FUNCTION public.guard_verification_evidence_linkage();
CREATE TRIGGER network_evidence_insert_guard BEFORE INSERT ON public.trip_distributions FOR EACH ROW WHEN (NEW.network_stripe_payment_intent_id IS NOT NULL OR NEW.network_payment_environment IS NOT NULL OR NEW.network_recipient_account_id IS NOT NULL) EXECUTE FUNCTION public.network_evidence_link_guard();
CREATE FUNCTION public.notify_verification_transition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.automatic_verification_level IS DISTINCT FROM OLD.automatic_verification_level AND NOT NEW.is_test_account THEN INSERT INTO public.notifications(user_id,type,title,body,link) SELECT m.user_id,'verification_requirement','Verification requirements changed','Sign in to review your current verification level and requirements.','/portal/account' FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=NEW.id AND m.role IN ('owner','admin') AND m.removed_at IS NULL AND NOT m.is_contractor AND p.status='active' AND p.deleted_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_verification_transition AFTER UPDATE OF automatic_verification_level ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.notify_verification_transition();
COMMENT ON COLUMN public.workspaces.automatic_verification_level IS 'Automatic server-side membership, business, protected document, Connect and explicit Network settlement evaluator; NULL retains separate legacy directory status.';